<template>
  <div class="page"><AppNav/><main>
    <header class="hero"><div><small>COURSE SPACES</small><h1>课程空间</h1><p>课程群聊、资料、讨论、作业和成员管理集中在一起。</p></div><div class="join"><el-input v-model="inviteCode" placeholder="输入课程邀请码" maxlength="8"/><el-button type="primary" @click="joinCourse">申请加入</el-button></div></header>
    <section class="course-list" v-if="spaces.length"><button v-for="item in spaces" :key="item.id" :class="['course-card',{active:item.id===selectedId}]" @click="select(item.id)"><b>{{ item.name }}</b><span>{{ item.college }} · {{ item.class_name }}</span><small>{{ item.teacher }} · {{ item.member_count }} 位成员</small></button></section>
    <el-empty v-if="!spaces.length" description="你还没有加入课程空间，请向任课教师获取邀请码"/>
    <section v-if="space.course" class="workspace" v-loading="loading">
      <div class="workspace-head"><div><small>COURSE SPACE</small><h2>{{ space.space.conversation_title || space.course.name }}</h2><p>{{ space.course.college }} · {{ space.course.class_name }} · {{ space.course.teacher }}</p></div><el-button type="primary" @click="openChat">进入课程群聊</el-button></div>
      <el-tabs v-model="tab"><el-tab-pane label="通知与概览" name="overview"><article v-for="n in notices" :key="n.id" class="card"><b>{{ n.is_pinned ? '置顶 · ' : '' }}{{ n.title }}</b><p>{{ n.content }}</p></article><el-empty v-if="!notices.length" description="暂无课程通知"/></el-tab-pane>
        <el-tab-pane label="课程资料" name="resources"><article v-for="r in resources" :key="r.id" class="card resource"><div><b>{{ r.title }}</b><p>{{ r.description }}</p><small>{{ r.file_name || r.type }} · {{ r.uploader_name || '课程教师' }}</small></div><a v-if="r.file_path" :href="r.file_path" target="_blank" rel="noopener">查看资料</a><a v-else-if="r.url" :href="r.url" target="_blank" rel="noopener">打开链接</a></article><el-empty v-if="!resources.length" description="教师还没有上传资料"/></el-tab-pane>
        <el-tab-pane label="课程讨论" name="discussions"><div class="new-post"><el-input v-model="newPost.title" placeholder="讨论标题" maxlength="60"/><el-input v-model="newPost.content" type="textarea" :rows="3" placeholder="发表课程讨论" maxlength="5000"/><el-button @click="publishPost">发布讨论</el-button></div><article v-for="post in discussions" :key="post.id" class="card"><b>{{ post.title }}</b><small>{{ post.author_name }} · {{ post.comment_count }} 条回复</small><p>{{ post.content }}</p></article><el-empty v-if="!discussions.length" description="暂无课程讨论"/></el-tab-pane>
        <el-tab-pane label="课程作业" name="tasks"><article v-for="task in tasks" :key="task.id" class="card"><b>{{ task.title }}</b><el-tag size="small">{{ task.task_type }}</el-tag><p>{{ task.description }}</p><small>截止：{{ task.due_at ? new Date(task.due_at).toLocaleString('zh-CN') : '未设置' }}</small><el-input v-model="task.draft" type="textarea" :rows="3" placeholder="填写作业提交内容"/><el-button size="small" @click="submitTask(task)">提交作业</el-button></article><el-empty v-if="!tasks.length" description="暂无已发布作业"/></el-tab-pane>
        <el-tab-pane label="成员管理" name="members"><article v-if="members.teacher" class="member"><b>教师：{{ members.teacher.name }}</b><span>课程管理员</span></article><article v-for="member in members.members" :key="member.id" class="member"><div><b>{{ member.name }}</b><small>{{ member.college }} · {{ member.class }} · {{ member.student_id }}</small></div><el-button size="small" @click="addFriend(member)" :disabled="member.id===me.id || member.is_friend || member.friend_request_pending">{{ member.is_friend ? '已是好友' : member.friend_request_pending ? '已申请' : '加好友' }}</el-button></article></el-tab-pane>
      </el-tabs>
    </section>
  </main></div>
</template>
<script setup>
import { onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import AppNav from '../components/AppNav.vue'
import { api } from '../utils/api'
import { sessionUser } from '../utils/session'

const router = useRouter(), me = sessionUser, spaces = ref([]), selectedId = ref(null), space = ref({}), notices = ref([]), resources = ref([]), discussions = ref([]), tasks = ref([]), members = ref({}), inviteCode = ref(''), tab = ref('overview'), loading = ref(false), newPost = ref({ title: '', content: '' })
async function loadSpaces () { spaces.value = await api('/courses/spaces'); if (!selectedId.value && spaces.value.length) selectedId.value = spaces.value[0].id; if (selectedId.value) await select(selectedId.value) }
async function select (id) { selectedId.value = id; loading.value = true; try { const [detail, noticeRows, resourceRows, discussionRows, taskRows, memberRows] = await Promise.all([api(`/courses/${id}/space`), api(`/courses/${id}/announcements`), api(`/resources?course_id=${id}`), api(`/courses/${id}/discussions`), api(`/courses/${id}/teacher-tasks`), api(`/courses/${id}/members`)]); space.value = detail; notices.value = noticeRows; resources.value = resourceRows; discussions.value = discussionRows; tasks.value = taskRows.map(item => ({ ...item, draft: item.submission?.content || '' })); members.value = memberRows } catch (error) { ElMessage.error(error.message) } finally { loading.value = false } }
async function joinCourse () { if (!inviteCode.value.trim()) return ElMessage.warning('请输入邀请码'); try { const result = await api('/courses/join', { method: 'POST', body: JSON.stringify({ invite_code: inviteCode.value }) }); ElMessage.success(result.message); inviteCode.value = '' } catch (error) { ElMessage.error(error.message) } }
function openChat () { if (space.value.space?.conversation_id) router.push({ path: '/messages', query: { conversation_id: space.value.space.conversation_id } }) }
async function publishPost () { if (!newPost.value.title.trim() || !newPost.value.content.trim()) return ElMessage.warning('请填写讨论标题和内容'); try { await api('/forum/posts', { method: 'POST', body: JSON.stringify({ ...newPost.value, course_id: selectedId.value }) }); newPost.value = { title: '', content: '' }; discussions.value = await api(`/courses/${selectedId.value}/discussions`); ElMessage.success('讨论已发布') } catch (error) { ElMessage.error(error.message) } }
async function submitTask (task) { if (!task.draft.trim()) return ElMessage.warning('请填写作业内容'); try { const result = await api(`/teacher-tasks/${task.id}/submit`, { method: 'POST', body: JSON.stringify({ content: task.draft }) }); ElMessage.success(result.message) } catch (error) { ElMessage.error(error.message) } }
async function addFriend (member) { if (member.id === me.value?.id) return; try { const result = await api('/friend-requests', { method: 'POST', body: JSON.stringify({ user_id: member.id }) }); ElMessage.success(result.message); member.friend_request_pending = 1 } catch (error) { ElMessage.error(error.message) } }
onMounted(loadSpaces)
</script>
<style scoped>
.page{min-height:100vh;background:#fffaf6;color:#633e2e}main{width:min(1180px,94vw);margin:auto;padding:34px 0 70px}.hero,.workspace-head{display:flex;justify-content:space-between;gap:22px;align-items:end}.hero h1{margin:6px 0;color:#633c2c;font-size:32px}.hero p,.workspace-head p{color:#97786a}.hero small,.workspace-head small{font-size:11px;letter-spacing:1.5px;color:#b2694e;font-weight:800}.join{display:flex;gap:8px;min-width:330px}.course-list{display:flex;gap:12px;overflow:auto;margin:28px 0}.course-card{border:1px solid #efdcd0;background:#fffdfa;border-radius:17px;padding:14px 16px;min-width:210px;text-align:left;color:#795b4d;cursor:pointer}.course-card.active{border-color:#cf7953;background:#fff0e5}.course-card b,.course-card span,.course-card small{display:block}.course-card span{margin-top:8px;color:#a87865;font-size:12px}.course-card small{margin-top:5px;color:#af9385;font-size:11px}.workspace{margin-top:24px;background:#fffdfa;border:1px solid #efdfd5;border-radius:23px;padding:22px;box-shadow:0 10px 30px #9f4c2b0d}.workspace-head{align-items:center;border-bottom:1px solid #f3e5dd;padding-bottom:16px}.workspace-head h2{margin:7px 0;color:#633c2c}.card{background:#fffaf6;border:1px solid #f0e1d8;border-radius:15px;padding:15px;margin:12px 0}.card b{color:#704432}.card p{white-space:pre-wrap;line-height:1.65;color:#81675c}.card small,.member small{display:block;color:#a38678;margin-top:7px}.resource{display:flex;justify-content:space-between;gap:15px}.resource a{color:#ae5d3e;text-decoration:none}.new-post{display:grid;gap:9px;margin:12px 0}.member{display:flex;justify-content:space-between;align-items:center;gap:15px}.member span{color:#ae816d;font-size:12px}@media(max-width:700px){.hero,.workspace-head{align-items:start;flex-direction:column}.join{width:100%;min-width:0}.resource,.member{align-items:start;flex-direction:column}}
</style>
